def halving(hypotheses, exps, truth, steps):
    alive = list(range(len(hypotheses)))
    mistakes = 0
    for t in range(steps):
        bit = {}
        w0 = 0.0
        w1 = 0.0
        for i in alive:
            h = hypotheses[i]
            b = h[t % len(h)]
            w = 2.0 ** (-exps[i])
            if b == '1':
                w1 += w
            else:
                w0 += w
        pred = '1'
        if w0 > w1:
            pred = '0'
        h = hypotheses[truth]
        actual = h[t % len(h)]
        if pred != actual:
            mistakes += 1
        keep = []
        for i in alive:
            g = hypotheses[i]
            if g[t % len(g)] == actual:
                keep.append(i)
        alive = keep
    return [mistakes, exps[truth]]

