def aixi_action(envs, history, horizon):
    def reward(env, acts):
        kind = env[0]
        a = acts[-1]
        if kind == 'const':
            if a == env[1]:
                return 1
            return 0
        if kind == 'alt':
            prev = 0
            if len(acts) > 1:
                prev = acts[-2]
            if a != prev:
                return 1
            return 0
        if kind == 'parity':
            if a == len(acts) % 2:
                return 1
            return 0
        return 0
    start = []
    acts0 = []
    for i in range(len(envs)):
        acts = []
        ok = True
        for a, r in history:
            acts.append(a)
            if reward(envs[i], acts) != r:
                ok = False
                break
        if ok:
            start.append(i)
    base = [a for a, r in history]
    def best(idx, acts, k):
        if k == 0 or len(idx) == 0:
            return [0.0, 0]
        total = 0.0
        for i in idx:
            total += 2.0 ** (-envs[i][2])
        top = -1.0
        arg = 0
        for a in range(2):
            na = acts + [a]
            g = [[], []]
            for i in idx:
                g[reward(envs[i], na)].append(i)
            v = 0.0
            for r in range(2):
                if len(g[r]) > 0:
                    w = 0.0
                    for i in g[r]:
                        w += 2.0 ** (-envs[i][2])
                    v += w / total * (r + best(g[r], na, k - 1)[0])
            if v > top + 1e-12:
                top = v
                arg = a
        return [top, arg]
    return best(start, base, horizon)

